  ('478ff191-d3d2-504e-a1d3-236aac8ecce0'::uuid, 'ee8a3f79-5347-5eae-8b1e-4fa14d3b0391'::uuid, 'mindset-knowledge-check', 'Think like a defender knowledge check', 70),
