  ('8fe561ca-5332-5034-bfe4-7934a206549c'::uuid, '29c0771b-d0f0-50ac-bb40-d1be261b5243'::uuid, 'recon-knowledge-check', 'Reconnaissance & enumeration knowledge check', 70),
