  ('2e07559e-8db8-59c9-8e90-f54de8b54d1c'::uuid, '478ff191-d3d2-504e-a1d3-236aac8ecce0'::uuid, 'Someone changes exam marks without permission. Which goal is most directly affected?', '["Confidentiality","Integrity","Availability"]'::jsonb, 1, 0),
  ('e0b8c347-2598-5e65-a1b4-5011d4016dd3'::uuid, '478ff191-d3d2-504e-a1d3-236aac8ecce0'::uuid, 'Which detail best helps prioritize two equally severe vulnerabilities?', '["The color of the dashboard","Whether the system is exposed and holds sensitive records","The length of the CVE identifier"]'::jsonb, 1, 1),
