  ('277d3296-398a-565b-ab2e-0a7b190c90d0'::uuid, '433b552e-756e-541c-bf03-9feffbe486d1'::uuid, 'Which is the strongest use of a historical incident?', '["Extract the failed assumption and compare current controls","Assume its exploit works against every present-day system","Repeat an unsourced cost statistic"]'::jsonb, 0, 0),
  ('ae254da0-91ed-5621-8c06-581ee0557845'::uuid, '433b552e-756e-541c-bf03-9feffbe486d1'::uuid, 'Do OSI layers and defense-in-depth rings describe exactly the same model?', '["No; they organize different aspects of a system","Yes, each has identical controls","Only when a service uses HTTPS"]'::jsonb, 0, 1),
  ('aa20cde6-87d7-5300-aac2-ac5b4c23adab'::uuid, '433b552e-756e-541c-bf03-9feffbe486d1'::uuid, 'Which statement best reflects Zero Trust?', '["Internal location alone should not grant broad access","One vendor product eliminates all trust decisions","Everything on a campus LAN is inherently trusted"]'::jsonb, 0, 2),
  ('36b2afc9-6045-5826-8ab6-929ea9d979b1'::uuid, 'e7bf4312-65cc-5e1e-860b-74f8265fa515'::uuid, 'Which configuration choice directly concerns network exposure?', '["The desktop wallpaper","The VM adapter’s network mode and routing","The name of the snapshot"]'::jsonb, 1, 0),
  ('eafb2fc9-dd11-53d1-a1de-8faf2bd48f2a'::uuid, 'e7bf4312-65cc-5e1e-860b-74f8265fa515'::uuid, 'Is installing Kali enough to establish a secure practice environment?', '["Yes, its tools handle every boundary","No; guest isolation, target selection, and scope still need configuration","Only if the VM runs full screen"]'::jsonb, 1, 1),
  ('b07057d1-0adc-5add-a4aa-af0542805a84'::uuid, 'e7bf4312-65cc-5e1e-860b-74f8265fa515'::uuid, 'What belongs in a useful preflight check?', '["Scope, target identity, network isolation, and intended actions","Only the tool’s logo","A promise to fix mistakes afterward"]'::jsonb, 0, 2),
