  ('6241b9eb-e774-5608-bf8a-3d09c8f13b23'::uuid, '4b5e937a-bd7d-565e-97c6-665b48a4b074'::uuid, 'Can an ordinary HTTPS packet capture always reveal the user’s password?', '["Yes, all packet captures show passwords","No; TLS normally encrypts the application payload","Only when the packet is large"]'::jsonb, 1, 1),
  ('da4fc9d3-774e-5ce4-ac16-51c8f384dc33'::uuid, '4b5e937a-bd7d-565e-97c6-665b48a4b074'::uuid, 'What is the main purpose of segmentation?', '["To restrict unnecessary communication between systems","To replace all authentication","To guarantee that software has no bugs"]'::jsonb, 0, 2),
  ('8df88137-42ef-594b-83c7-c648e257e0f3'::uuid, '853fcd69-5c8a-5901-bc4c-ce558988383f'::uuid, 'What should you do before running an unfamiliar command from the internet?', '["Run it as administrator","Understand it and verify its source and effects","Disable security tools"]'::jsonb, 1, 0),
  ('6cf6fc5e-cfcf-5641-a5c4-51e18393b92d'::uuid, '853fcd69-5c8a-5901-bc4c-ce558988383f'::uuid, 'For an owner-only private file, which basic mode is the best fit?', '["777: everyone can read, write, execute","600: owner can read and write","666: everyone can read and write"]'::jsonb, 1, 1),
