  ('f8c63cc3-359b-50d3-aae9-1d3ecba8952e'::uuid, 'ce23842e-6aec-545b-8f8b-e6dd9a83d5e3'::uuid, 'Does hiding a window reduce the privileges of a process?', '["No; UI appearance and process authority are different","Yes, invisible windows cannot act","Only on older Windows versions"]'::jsonb, 0, 1),
  ('c926097c-ac4a-5b39-a459-1c019da81687'::uuid, 'ce23842e-6aec-545b-8f8b-e6dd9a83d5e3'::uuid, 'Which distinction is accurate?', '["An exploit and a post-compromise implant serve different roles","Every SMB server is vulnerable to the same exploit","A version banner proves successful exploitation"]'::jsonb, 0, 2),
