  ('f61b50db-26a0-5a4d-8854-d0b6cb0f5f4d'::uuid, '92fc50c5-c8e2-53b1-a2bf-d4612b96c0be'::uuid, 'Which approach is suitable for password storage?', '["Base64 encoding","A purpose-built salted password hash","Plain text in a hidden file"]'::jsonb, 1, 1),
