  ('f9caf074-8d92-5cf8-b26a-dad959fe5c53'::uuid, '8fe561ca-5332-5034-bfe4-7934a206549c'::uuid, 'Which is the best enumeration result?', '["A screenshot with no target or time","A scoped observation with source, timestamp, confidence, and owner","A long list of unverified internet addresses"]'::jsonb, 1, 2),
