  ('f372f56e-80d7-5bf3-990a-6ed15f160717'::uuid, 'dcee2c42-853e-5fa6-9bdb-e16e3a027e89'::uuid, 'What should happen before calling a scanner finding confirmed?', '["Verify applicability and the supporting evidence","Run every exploit found online","Copy its severity into a report without review"]'::jsonb, 0, 1),
