  ('d993c068-8552-5339-a025-6c1ddbabb321'::uuid, '598ad162-81a7-578c-842d-634b14c2a4d8'::uuid, 'What is the most useful addition to a normal feature test?', '["An abuse case that checks a trust boundary","A second identical happy-path test","A screenshot with no explanation"]'::jsonb, 0, 2),
  ('89054ded-7d2c-50d8-b79f-c28a87dc82d6'::uuid, 'e893c01f-b663-5bd5-a495-ac556589a792'::uuid, 'Which question should guide an individual web test?', '["Which trust assumption am I checking?","How many tools can I launch at once?","Can I hide my requests from the application owner?"]'::jsonb, 0, 0),
  ('b9dcf208-8ff0-5b4d-9005-4a8d4c2b362b'::uuid, 'e893c01f-b663-5bd5-a495-ac556589a792'::uuid, 'Which statement about encoding is accurate?', '["One encoding function is safe in every context","The required encoding depends on the output context","Base64 removes all injection risks"]'::jsonb, 1, 1),
