  ('7e5962eb-6ab9-54f4-bc0f-015a312ed83e'::uuid, 'a7b39fe6-1776-5ec9-a726-72fd8c9a09ef'::uuid, 'Does ARP redirection alone guarantee decryption of correctly validated HTTPS?', '["No","Yes, TLS no longer matters","Only if the router has a short name"]'::jsonb, 0, 0),
