  ('078dd9e4-3e29-5a5c-992c-1cc2078f3a37'::uuid, '424a5738-765a-58c8-a65d-fce632493b4f'::uuid, 'Does an exploit framework’s success message replace a finding’s evidence and impact analysis?', '["No","Yes, all successful sessions prove equal impact","Only when a paid edition is used"]'::jsonb, 0, 0),
  ('264a0bad-4da0-502f-b3c8-f97ce7549cd6'::uuid, '424a5738-765a-58c8-a65d-fce632493b4f'::uuid, 'What makes the echo exercise different from a remote shell?', '["It returns a bounded message without executing operating-system commands","It uses a different wallpaper","Every socket program is automatically a shell"]'::jsonb, 0, 1),
  ('e3133b41-d599-5a0b-a495-8bf1d57ab9ef'::uuid, '424a5738-765a-58c8-a65d-fce632493b4f'::uuid, 'Which activity belongs in the closeout of an authorized assessment?', '["Leaving a hidden account for next time","Removing temporary access and validating cleanup with the owner","Publishing any recovered credentials"]'::jsonb, 1, 2),
  ('070ec4ef-871a-5eb5-abd9-c105a1504c53'::uuid, '11449a8f-35f2-5717-8f9b-51b403fbaf64'::uuid, 'A SIEM produces an alert. What is the best first interpretation?', '["A confirmed breach","A signal to investigate in context","Proof the firewall failed"]'::jsonb, 1, 0),
  ('2890a4d4-8a76-50b8-9aa4-c8f318e294de'::uuid, '11449a8f-35f2-5717-8f9b-51b403fbaf64'::uuid, 'In ATT&CK, what does a tactic primarily describe?', '["The attacker’s objective","A product’s price","A file extension"]'::jsonb, 0, 1),
  ('f0927449-e95d-5859-85b0-60abad60b8e3'::uuid, '11449a8f-35f2-5717-8f9b-51b403fbaf64'::uuid, 'Which handover is most useful?', '["“Looks bad, please check”","A timeline with evidence, confidence, scope, and next actions","Only an alert ID with no context"]'::jsonb, 1, 2),
  ('dd8a5b06-bf0f-54c5-a736-60b5812194b8'::uuid, 'e20c50ae-c5c0-5be2-8dc1-f47c92467994'::uuid, 'Who typically controls whether a customer’s storage bucket is publicly readable?', '["Only the data-center guard","The customer through configuration and access policy","No one"]'::jsonb, 1, 0),
  ('7ca3189b-b497-576e-a8cc-854ac4205e8c'::uuid, 'e20c50ae-c5c0-5be2-8dc1-f47c92467994'::uuid, 'A cloud key was committed to a public repository. What is a priority action?', '["Rename the repository","Revoke or rotate the key and investigate its use","Delete only the latest visible line"]'::jsonb, 1, 1),
