  ('dbd40843-5627-5129-a076-4292006efc76'::uuid, 'dd8d52c7-e3c0-5446-9268-f34d8546f386'::uuid, 'What can a static string alone prove?', '["That the text is present in the inspected representation, with context still needed","That the corresponding code definitely executed","That the file is harmless"]'::jsonb, 0, 0),
  ('dfaee977-52d0-5b6e-a8e7-b14e22999ba0'::uuid, 'dd8d52c7-e3c0-5446-9268-f34d8546f386'::uuid, 'Does an ordinary-looking error dialog prove that a program did nothing else?', '["Yes","No; UI appearance does not establish the program’s behavior","Only if the dialog uses a system icon"]'::jsonb, 1, 1),
  ('8cbb7fdd-1482-5ab4-b7d4-ea055aa0b876'::uuid, 'dd8d52c7-e3c0-5446-9268-f34d8546f386'::uuid, 'Why is exact-file-hash matching insufficient by itself?', '["A changed representation can produce a different hash","All hashes are reversible","A matching hash proves that every program is malicious"]'::jsonb, 0, 2),
