  ('fe338f52-33a2-5782-a69d-1445d62df8b4'::uuid, 'f16ccbf6-786a-503f-b1bf-5991df881dc2'::uuid, 'Why might an IP reputation match be misleading?', '["An address can be shared or reassigned","All IP addresses are permanent identities","Reputation scores are always definitive"]'::jsonb, 0, 1),
