  ('e5735221-5932-5040-b3b5-7260b81b176c'::uuid, '35461d1a-c006-5dc8-83c9-9483b7bfa406'::uuid, 'Which CSF 2.0 function explicitly addresses organizational direction and oversight?', '["Govern","Compile","Deploy"]'::jsonb, 0, 0),
  ('b7f8e90e-dd74-52ad-ada0-fb83bc1c2eaa'::uuid, '35461d1a-c006-5dc8-83c9-9483b7bfa406'::uuid, 'What is residual risk?', '["Risk remaining after controls are applied","The number of old tickets","Risk that no one owns"]'::jsonb, 0, 1),
